    )
    /**
     * Make `root[id]` a map holding exactly `fields` (`reconcileRecords`
     * body): absent keys are deleted, a field is only written when its value
     * actually changed, so unrelated concurrent edits merge.
     */
    case replaceRecord(
        /**
         * Which collection.
         */root: CrdtRoot, 
        /**
         * The record id.
         */id: String, 
        /**
         * The complete field set.
         */fields: [CrdtField]
    )
    /**
     * `root.delete(id)`.
     */
    case deleteRecord(
        /**
         * Which collection.
         */root: CrdtRoot, 
        /**
         * The record id.
         */id: String
    )
    /**
