     * between the common prefix and suffix (`replaceText`).
     */
    case replaceText(
        /**
         * The widget id.
         */id: String, 
        /**
         * The whole new text.
         */text: String
    )
    /**
     * `texts.delete(id)`.
     */
    case deleteText(
        /**
         * The widget id.
         */id: String
    )
    /**
     * Delete every key of `root` not in `ids` (a first write with no previous
     * snapshot walks `root.keys()`).
     */
    case retainRecords(
        /**
         * Which collection.
         */root: CrdtRoot, 
        /**
         * The ids that stay.
         */ids: [String]
    )
    /**
     * Delete every `texts` key not in `ids`.
     */
